function parseRange(range){
  var r = String(range == null ? '' : range).trim();
  if (!r) return { kind:'empty', risk:3, note:'空范围，安装行为不确定' };
  if (/^(file|link):/.test(r)) return { kind:'file', risk:2, note:'本地路径依赖，CI 上大概率装不上' };
  if (/^workspace:/.test(r)) return { kind:'workspace', risk:0, note:'工作区内部依赖' };
  if (/^(git\+|git:|github:|https?:)/.test(r)) return { kind:'git', risk:3, note:'Git 源依赖，无版本锁定与审计' };
  if (/^npm:/.test(r)) return { kind:'alias', risk:1, note:'别名依赖，注意实际包名' };
  if (r === '*' || r === 'x' || r === 'latest' || r === '') return { kind:'any', risk:3, note:'任意版本，随时可能被破坏性升级击穿' };
  if (/^\d+\.\d+\.\d+([-+].*)?$/.test(r)) return { kind:'exact', risk:0, note:'锁定精确版本' };
  if (/^\^/.test(r)){
    var m = /^\^(\d+)\./.exec(r);
    if (m && m[1] === '0') return { kind:'caret0', risk:2, note:'0.x 的 ^ 只锁次版本，社区约定并不可靠' };
    return { kind:'caret', risk:1, note:'允许次版本与补丁升级' };
  }
  if (/^~/.test(r)) return { kind:'tilde', risk:1, note:'仅允许补丁升级' };
  if (/^\d+\.x$|^\d+$/.test(r)) return { kind:'major', risk:2, note:'只锁主版本，次版本自由跳' };
  if (/[<>]/.test(r)) return { kind:'range', risk:2, note:'区间范围，解析结果依赖注册表当前状态' };
  if (/\|\|/.test(r)) return { kind:'union', risk:2, note:'多段并集范围，容易在不同环境解析出不同版本' };
  return { kind:'other', risk:2, note:'非常规范围表达式' };
}

function parsePackageJson(text){
  var obj;
  try { obj = JSON.parse(String(text == null ? '' : text)); }
  catch (e){ return { ok:false, error:'JSON 解析失败：' + e.message, deps:[] }; }
  if (!obj || typeof obj !== 'object') return { ok:false, error:'顶层不是对象', deps:[] };
  var groups = [['dependencies','runtime'], ['devDependencies','dev'], ['peerDependencies','peer'], ['optionalDependencies','optional']];
  var deps = [], seen = {};
  for (var g = 0; g < groups.length; g++){
    var src = obj[groups[g][0]] || {};
    for (var k in src){
      if (!Object.prototype.hasOwnProperty.call(src, k)) continue;
      var info = parseRange(src[k]);
      deps.push({ name:k, range:String(src[k]), scope:groups[g][1], kind:info.kind, risk:info.risk, note:info.note });
      seen[k] = (seen[k] || []).concat(groups[g][1]);
    }
  }
  var dupes = [];
  for (var n in seen) if (Object.prototype.hasOwnProperty.call(seen, n) && seen[n].length > 1) dupes.push({ name:n, scopes:seen[n] });
  return {
    ok:true, error:null, name:obj.name || '', version:obj.version || '',
    deps:deps, dupes:dupes,
    hasEngines: !!obj.engines, hasLockScripts: !!(obj.scripts && (obj.scripts.preinstall || obj.scripts.postinstall)),
    pm: obj.packageManager || ''
  };
}

function depReport(pkg){
  if (!pkg.ok) return { total:0, score:0, buckets:{}, issues:[{level:'bad', msg:pkg.error}] };
  var deps = pkg.deps, buckets = {}, issues = [], riskSum = 0;
  for (var i = 0; i < deps.length; i++){
    buckets[deps[i].kind] = (buckets[deps[i].kind] || 0) + 1;
    riskSum += deps[i].risk;
    if (deps[i].risk >= 3) issues.push({ level:'bad', msg:deps[i].name + ' → ' + deps[i].range + '：' + deps[i].note });
    else if (deps[i].risk === 2) issues.push({ level:'warn', msg:deps[i].name + ' → ' + deps[i].range + '：' + deps[i].note });
  }
  for (var d = 0; d < pkg.dupes.length; d++) issues.push({ level:'warn', msg:pkg.dupes[d].name + ' 同时出现在 ' + pkg.dupes[d].scopes.join(' / ') + '，解析优先级容易踩坑' });
  if (!pkg.pm) issues.push({ level:'warn', msg:'未声明 packageManager 字段，团队成员可能用不同包管理器' });
  if (pkg.hasLockScripts) issues.push({ level:'warn', msg:'存在 pre/postinstall 脚本，供应链攻击的常见落点' });
  var runtime = deps.filter(function(x){ return x.scope === 'runtime'; }).length;
  if (runtime > 40) issues.push({ level:'warn', msg:'运行时依赖 ' + runtime + ' 个，构建体积与审计面都偏大' });
  var avg = deps.length ? riskSum / deps.length : 0;
  var score = Math.max(0, Math.round(100 - avg * 22 - pkg.dupes.length * 5 - (pkg.hasLockScripts ? 8 : 0)));
  return { total:deps.length, runtime:runtime, buckets:buckets, issues:issues, avgRisk:Math.round(avg * 100) / 100, score:score };
}

function parseGraph(text){
  var lines = String(text == null ? '' : text).split(/\r?\n/);
  var edges = [], errors = [];
  for (var i = 0; i < lines.length; i++){
    var l = lines[i].trim();
    if (!l || l.charAt(0) === '#') continue;
    var parts = l.split(/->|=>/);
    if (parts.length < 2){ errors.push({ line:i + 1, text:l }); continue; }
    var from = parts[0].trim();
    if (!from){ errors.push({ line:i + 1, text:l }); continue; }
    var tos = parts.slice(1).join('->').split(/[,\s]+/).filter(function(x){ return x; });
    for (var j = 0; j < tos.length; j++) edges.push({ from:from, to:tos[j] });
    if (!tos.length) edges.push({ from:from, to:null });
  }
  return { edges:edges, errors:errors };
}

function buildGraph(edges){
  var adj = {}, indeg = {}, nodes = {};
  function touch(n){ if (!adj[n]){ adj[n] = []; indeg[n] = 0; nodes[n] = 1; } }
  for (var i = 0; i < edges.length; i++){
    var e = edges[i];
    touch(e.from);
    if (e.to === null || e.to === undefined) continue;
    touch(e.to);
    if (adj[e.from].indexOf(e.to) < 0){ adj[e.from].push(e.to); indeg[e.to]++; }
  }
  return { adj:adj, indeg:indeg, names:Object.keys(nodes).sort() };
}

function findCycles(g){
  var color = {}, stack = [], cycles = [], seen = {};
  function dfs(n){
    color[n] = 1; stack.push(n);
    var next = g.adj[n] || [];
    for (var i = 0; i < next.length; i++){
      var m = next[i];
      if (color[m] === 1){
        var idx = stack.indexOf(m);
        var cyc = stack.slice(idx).concat([m]);
        var key = cyc.slice().sort().join('|');
        if (!seen[key]){ seen[key] = 1; cycles.push(cyc); }
      } else if (!color[m]) dfs(m);
    }
    color[n] = 2; stack.pop();
  }
  for (var i = 0; i < g.names.length; i++) if (!color[g.names[i]]) dfs(g.names[i]);
  return cycles;
}

function topoOrder(g){
  var indeg = {}, i;
  for (i = 0; i < g.names.length; i++) indeg[g.names[i]] = g.indeg[g.names[i]] || 0;
  var queue = g.names.filter(function(n){ return indeg[n] === 0; }).sort(), out = [];
  while (queue.length){
    var n = queue.shift();
    out.push(n);
    var next = (g.adj[n] || []).slice().sort();
    for (i = 0; i < next.length; i++){
      indeg[next[i]]--;
      if (indeg[next[i]] === 0) queue.push(next[i]);
    }
    queue.sort();
  }
  return { order:out, complete: out.length === g.names.length };
}

function depths(g){
  var memo = {}, guard = {};
  function walk(n){
    if (memo[n] !== undefined) return memo[n];
    if (guard[n]) return 0;
    guard[n] = 1;
    var best = 0, next = g.adj[n] || [];
    for (var i = 0; i < next.length; i++) best = Math.max(best, 1 + walk(next[i]));
    guard[n] = 0;
    memo[n] = best;
    return best;
  }
  var out = {};
  for (var i = 0; i < g.names.length; i++) out[g.names[i]] = walk(g.names[i]);
  return out;
}

function metrics(g){
  var d = depths(g), rows = [];
  for (var i = 0; i < g.names.length; i++){
    var n = g.names[i];
    rows.push({ name:n, fanOut:(g.adj[n] || []).length, fanIn:g.indeg[n] || 0, depth:d[n] });
  }
  rows.sort(function(a, b){ return b.fanIn - a.fanIn || b.fanOut - a.fanOut || (a.name < b.name ? -1 : 1); });
  var maxDepth = 0;
  for (var k = 0; k < rows.length; k++) maxDepth = Math.max(maxDepth, rows[k].depth);
  var leaves = rows.filter(function(r){ return r.fanOut === 0; }).length;
  var roots = rows.filter(function(r){ return r.fanIn === 0; }).length;
  var edges = rows.reduce(function(s, r){ return s + r.fanOut; }, 0);
  return { rows:rows, nodes:rows.length, edges:edges, maxDepth:maxDepth, leaves:leaves, roots:roots,
           density: rows.length > 1 ? Math.round(edges / (rows.length * (rows.length - 1)) * 1000) / 1000 : 0 };
}

function analyze(graphText){
  var p = parseGraph(graphText);
  var g = buildGraph(p.edges);
  var cyc = findCycles(g);
  var topo = topoOrder(g);
  var mt = metrics(g);
  var health = 100;
  health -= cyc.length * 20;
  if (mt.maxDepth > 8) health -= 10;
  if (mt.nodes && mt.roots === 0) health -= 15;
  health -= p.errors.length * 5;
  return { graph:g, cycles:cyc, topo:topo, metrics:mt, errors:p.errors, health:Math.max(0, health) };
}

function dotOutput(g, cycles){
  var inCycle = {};
  for (var c = 0; c < cycles.length; c++) for (var j = 0; j < cycles[c].length; j++) inCycle[cycles[c][j]] = 1;
  var out = ['digraph deps {', '  rankdir=LR;', '  node [shape=box, style=rounded];'];
  for (var i = 0; i < g.names.length; i++){
    var n = g.names[i];
    out.push('  "' + n + '"' + (inCycle[n] ? ' [color=red]' : '') + ';');
  }
  for (var k = 0; k < g.names.length; k++){
    var f = g.names[k], next = g.adj[f] || [];
    for (var t = 0; t < next.length; t++) out.push('  "' + f + '" -> "' + next[t] + '";');
  }
  out.push('}');
  return out.join('\n');
}

var DepGraphForgePure = {
  parseRange: parseRange, parsePackageJson: parsePackageJson, depReport: depReport,
  parseGraph: parseGraph, buildGraph: buildGraph, findCycles: findCycles, topoOrder: topoOrder,
  depths: depths, metrics: metrics, analyze: analyze, dotOutput: dotOutput
};
if (typeof module !== 'undefined' && module.exports) module.exports = DepGraphForgePure;
if (typeof window !== 'undefined') window.DepGraphForgePure = DepGraphForgePure;
